import {createChatOrchestrator} from './chatOrchestrator.js';
import {createMockProvider} from '../providers/mock/mockProvider.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {ChatSession} from '../types/session.js';

it('preserves rejected values as onError causes and caller rejections [spec: specs/hal-engine-config-hooks/spec.md#8]', async () => {
  const results = [];
  const failures: unknown[] = ['string boom', {code: 503}, undefined, new Error('original')];
  for (const failure of failures) {
    const received: Error[] = [];
    const order: string[] = [];
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
    const orchestrator = createChatOrchestrator(
      createMockProvider(),
      new PromptBuilder({identity: 'Assistant'}),
      undefined,
      {
        hooks: {
          beforeSession: async () => {
            throw failure;
          },
          onError: async (_session, error) => {
            received.push(error);
            order.push('onError');
          },
          afterSession: async () => void order.push('afterSession'),
        },
      }
    );
    const rejection = await orchestrator.processMessage(session).then(
      () => ({rejected: false, value: undefined}),
      (value: unknown) => ({rejected: true, value})
    );
    const error = received[0];
    results.push({
      count: received.length,
      isError: error instanceof Error,
      readable: Boolean(error?.message),
      original: failure instanceof Error ? error === failure : error?.cause === failure,
      rejected: rejection.rejected && rejection.value === failure,
      order,
    });
  }
  expect(results).toEqual(failures.map(() => ({
    count: 1,
    isError: true,
    readable: true,
    original: true,
    rejected: true,
    order: ['onError', 'afterSession'],
  })));
});
EOF
timeout 300 node --experimental-vm-modules node_modules/jest/bin/jest.js --runTestsByPath src/orchestration/rejectionHooks.test.ts --runInBand"
